package com.google.javascript.rhino.jstype;

import com.google.common.base.Predicate;
import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.jstype.JSTypeRegistry.ResolveMode;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Comparator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Spy;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class JSType_getRestrictedTypeGivenToBooleanOutcome_TriageGen2Test {

    @Spy
    private JSType jsTypeSpy;

    @Spy
    private BooleanLiteralSet mockLiterals;

    @Before
    public void setUp() {
        // We use a spy on JSType to control the behavior of internal method calls 
        // like getPossibleToBooleanOutcomes() and getNativeType()
        // while testing the actual logic of getRestrictedTypeGivenToBooleanOutcome.
    }

    /**
     * Test case where the outcome is present in the possible boolean outcomes.
     * This covers the 'if' branch.
     */
    @Test
    public void testGetRestrictedTypeGivenToBooleanOutcome_TrueBranch() {
        // Setup: outcome is true, and literals contains true
        boolean outcome = true;

        // Mocking the internal dependencies via the spy
        // Note: Since getPossibleToBooleanOutcomes is likely internal/protected, 
        // we stub the spy to return our mock literals.
        doReturn(mockLiterals).when(jsTypeSpy).getPossibleToBooleanOutcomes();
        when(mockLiterals.contains(outcome)).thenReturn(true);

        // Execute
        JSType result = jsTypeSpy.getRestrictedTypeGivenToBooleanOutcome(outcome);

        // Verify: result should be 'this' (the spy itself)
        assertEquals("Should return 'this' when outcome is in literals", jsTypeSpy, result);
    }

    /**
     * Test case where the outcome is NOT present in the possible boolean outcomes.
     * This covers the 'else' branch.
     */
    @Test
    public void testGetRestrictedTypeGivenToBooleanOutcome_FalseBranch() {
        // Setup: outcome is false, but literals does NOT contain false
        boolean outcome = false;
        JSType noType = mock(JSType.class);

        doReturn(mockLiterals).when(jsTypeSpy).getPossibleToBooleanOutcomes();
        when(mockLiterals.contains(outcome)).thenReturn(false);
        // Stub getNativeType to return our mock noType
        doReturn(noType).when(jsTypeSpy).getNativeType(JSTypeNative.NO_TYPE);

        // Execute
        JSType result = jsTypeSpy.getRestrictedTypeGivenToBooleanOutcome(outcome);

        // Verify: result should be the NO_TYPE returned by getNativeType
        assertEquals("Should return NO_TYPE when outcome is not in literals", noType, result);
    }

    /**
     * Test case for the other boolean value to ensure full branch coverage.
     */
    @Test
    public void testGetRestrictedTypeGivenToBooleanOutcome_AlternativeFalseBranch() {
        // Setup: outcome is true, but literals does NOT contain true
        boolean outcome = true;
        JSType noType = mock(JSType.class);

        doReturn(mockLiterals).when(jsTypeSpy).getPossibleToBooleanOutcomes();
        when(mockLiterals.contains(outcome)).thenReturn(false);
        doReturn(noType).when(jsTypeSpy).getNativeType(JSTypeNative.NO_TYPE);

        // Execute
        JSType result = jsTypeSpy.getRestrictedTypeGivenToBooleanOutcome(outcome);

        // Verify
        assertEquals("Should return NO_TYPE when outcome is not in literals", noType, result);
    }
}
